vector<int> dailyTemperaturesSpan_16(const vector<int>& t) { int n = t.size(); vector<int> ans(n, 0); vector<int> st; for (int i = 0; i < n; ++i) { while (!st.empty() && t[i] > t[st.back()]) { int idx = st.back(); st.pop_back(); ans[idx] = i - idx; } st.push_back(i); } return ans; }
vector<int> reverseVectorStack_16(const vector<int>& a) { vector<int> st; for (int x : a) st.push_back(x); vector<int> r; while (!st.empty()) { r.push_back(st.back()); st.pop_back(); } return r; }
string removeAdjacentDuplicates_16(const string& s) { string st; for (char c : s) { if (!st.empty() && st.back() == c) st.pop_back(); else st.push_back(c); } return st; }
